html,body{height:100%;}
body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:#e2e8f0;background:#1e293b;-webkit-font-smoothing:antialiased;overflow:hidden;}
.wrap{position:relative;box-sizing:border-box;height:100%;overflow:hidden;display:flex;flex-direction:column;}
.close{position:absolute;top:13px;right:13px;width:34px;height:34px;border:1px solid #3b4d67;background:#1e293b;color:#e2e8f0;font-size:16px;line-height:1;cursor:pointer;border-radius:9px;z-index:5;transition:.15s;box-shadow:0 2px 8px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center;}
.close:hover{background:#ef4444;border-color:#ef4444;color:#fff;}
.hero{flex:0 0 auto;padding:20px 32px 16px;background:#172033;border-bottom:1px solid #334155;}
.eyebrow{display:flex;align-items:center;gap:10px;color:#9fbce6;font-size:11px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;margin-bottom:9px;}
.eyebrow .env{width:26px;height:26px;border-radius:8px;background:rgba(96,165,250,.18);display:flex;align-items:center;justify-content:center;font-size:14px;}
.subject{font-size:17px;font-weight:800;color:#f8fafc;line-height:1.35;padding-right:42px;word-break:break-word;letter-spacing:-.01em;}
.badges{display:flex;gap:9px;margin-top:12px;flex-wrap:wrap;}
.badge{display:inline-flex;align-items:center;gap:7px;padding:5px 13px;border-radius:20px;font-size:12px;font-weight:700;}
.badge .d{width:7px;height:7px;border-radius:50%;}
.b-error{background:rgba(248,113,113,.15);color:#fca5a5;} .b-error .d{background:#f87171;}
.b-warning{background:rgba(251,191,36,.15);color:#fcd34d;} .b-warning .d{background:#fbbf24;}
.b-info{background:rgba(96,165,250,.15);color:#93c5fd;} .b-info .d{background:#60a5fa;}
.b-default{background:rgba(148,163,184,.15);color:#cbd5e1;} .b-default .d{background:#94a3b8;}
.split{display:flex;align-items:stretch;flex:1;min-height:0;overflow:hidden;}
.pane{padding:20px 28px 22px;box-sizing:border-box;overflow-y:auto;}
.pane-left{flex:0 0 44%;max-width:44%;border-right:1px solid #2b3a52;}
.pane-right{flex:1;min-width:0;display:flex;flex-direction:column;}
.pane-title{color:#aab7c9;font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;margin-bottom:12px;}
.field{padding:9px 0;border-bottom:1px solid #22304657;}
.field:last-child{border-bottom:none;}
.field .lbl{color:#7d8ea6;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-bottom:3px;}
.field .val{color:#e8eef7;font-size:14px;font-weight:500;word-break:break-word;line-height:1.35;}
.events-empty{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;min-height:200px;border:1px dashed #334155;border-radius:12px;color:#64748b;background:#0f172a80;}
.events-empty .ico{font-size:34px;opacity:.55;}
.events-empty .txt{font-size:13px;font-style:italic;}
.evtlist{display:flex;flex-direction:column;gap:8px;overflow:auto;}
.evt{display:flex;align-items:flex-start;gap:12px;background:#0f172a;border:1px solid #26344b;border-radius:10px;padding:12px 15px;}
.evt .d{width:9px;height:9px;border-radius:50%;margin-top:5px;flex:0 0 auto;background:#475569;}
.evt.err .d{background:#f87171;} .evt.warn .d{background:#fbbf24;} .evt.on .d{background:#22c55e;}
.evt .en{flex:1;min-width:0;}
.evt .nm{font-size:13px;font-weight:700;color:#e8eef7;text-transform:capitalize;}
.evt .rs{font-size:12px;color:#94a3b8;margin-top:3px;word-break:break-word;}
.evt .tm{font-size:12px;color:#7d8ea6;white-space:nowrap;}
.skel{padding:60px;text-align:center;color:#94a3b8;}
@media(max-width:680px){.split{flex-direction:column}.pane-left{flex:none;max-width:none;border-right:none;border-bottom:1px solid #2b3a52}}

